import{_ as d,o as t,c as o,a2 as c}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Команды CLI","description":"","frontmatter":{},"headers":[],"relativePath":"ru/cli/overview.md","filePath":"ru/cli/overview.md","lastUpdated":1784903584000}'),r={name:"ru/cli/overview.md"};function a(i,e,l,n,s,h){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="команды-cli" tabindex="-1">Команды CLI <a class="header-anchor" href="#команды-cli" aria-label="Permalink to &quot;Команды CLI&quot;">​</a></h1><h2 id="обзор" tabindex="-1">Обзор <a class="header-anchor" href="#обзор" aria-label="Permalink to &quot;Обзор&quot;">​</a></h2><p>CLI <code>swag2mcp</code> — это единая точка входа для всех операций: от инициализации рабочей области и управления спецификациями API до запуска MCP-сервера для интеграции с LLM. Он предоставляет <strong>13 команд</strong>, охватывающих полный жизненный цикл работы со спецификациями OpenAPI/Swagger/Postman.</p><h3 id="что-решает-cli" tabindex="-1">Что решает CLI <a class="header-anchor" href="#что-решает-cli" aria-label="Permalink to &quot;Что решает CLI&quot;">​</a></h3><ul><li><strong>Жизненный цикл рабочей области</strong> — создание (<code>init</code>), просмотр (<code>info</code>, <code>ls</code>), очистка (<code>clean</code>), обновление (<code>update</code>) и удаление (<code>delete</code>) рабочих областей и их содержимого</li><li><strong>Управление спецификациями и коллекциями</strong> — добавление (<code>add</code>), просмотр (<code>ls</code>) и удаление (<code>delete</code>) спецификаций API и их коллекций</li><li><strong>Режимы запуска</strong> — запуск MCP-сервера для доступа LLM к инструментам (<code>mcp</code>) или запуск интерактивного TUI-обозревателя (<code>run</code>)</li><li><strong>Диагностика</strong> — проверка конфигурации (<code>validate</code>), показ версии (<code>version</code>), отображение информации о runtime (<code>info</code>)</li><li><strong>Резервное копирование и восстановление</strong> — полный цикл рабочей области через ZIP (<code>export</code>, <code>import</code>)</li></ul><h3 id="ключевые-нюансы" tabindex="-1">Ключевые нюансы <a class="header-anchor" href="#ключевые-нюансы" aria-label="Permalink to &quot;Ключевые нюансы&quot;">​</a></h3><ul><li><strong>Разрешение пути</strong> — команды, принимающие <code>[path]</code>, ожидают <strong>директорию рабочей области</strong> (не путь к файлу). Порядок разрешения: явный <code>[path]</code> → текущая директория (<code>./</code>) → <code>~/.swag2mcp/</code>. CLI автоматически добавляет <code>swag2mcp.yaml</code>. Всегда передавайте явный путь при запуске в качестве сервиса или в конфиге IDE, чтобы избежать загрузки не той рабочей области.</li><li><strong>Спецификация vs Коллекция</strong> — <strong>спецификация</strong> представляет логический API-сервис (например, &quot;Open-Meteo API&quot;), а <strong>коллекция</strong> — это один файл OpenAPI/Swagger/Postman. Спецификация может иметь несколько коллекций.</li><li><strong><code>--version</code></strong> поддерживается как флаг (<code>swag2mcp --version</code>), так и подкоманда (<code>swag2mcp version</code>).</li><li><strong><code>add spec</code> / <code>add collection</code></strong> принимают YAML-ввод через <code>--yaml</code> (строка или <code>-</code> для stdin). Передача через файл или heredoc позволяет избежать проблем с экранированием специальных символов в оболочке.</li><li><strong><code>delete</code></strong> требует TTY (интерактивный терминал). Нет флага <code>--force</code> или <code>--yes</code> — всегда запрашивает выбор и подтверждение.</li><li><strong><code>mcp</code></strong> — основная команда для интеграции с LLM. Поддерживает три транспорта: <code>stdio</code> (по умолчанию), <code>sse</code> и <code>streamable-http</code>. Флаг <code>--disable-llm-auth</code> (по умолчанию: <code>true</code>) удаляет инструмент <code>auth</code> из списка MCP-инструментов, предотвращая просмотр или запрос токенов LLM. Аутентификация всё равно работает — токены получаются через стандартный механизм конфига, а не через LLM. Этот режим рекомендуется для <strong>продакшена</strong> (LLM никогда не имеет доступа к учётным данным). Для <strong>отладки</strong> или при использовании короткоживущих токенов установите <code>--disable-llm-auth=false</code>, чтобы LLM могла запрашивать свежие токены через инструмент <code>auth</code>.</li><li><strong><code>validate</code></strong> проверяет синтаксис YAML, структуру конфига, существование файлов спецификаций, доступность URL, формат спецификаций (OpenAPI/Swagger/Postman), настройки аутентификации и корректность HTTP-клиента. Он <strong>не</strong> тестирует эндпоинты аутентификации или доступность API-эндпоинтов.</li><li><strong><code>export</code> / <code>import</code></strong> обеспечивают полный цикл рабочей области — файл конфига, файлы спецификаций, кэш и скрипты аутентификации включаются в ZIP-архив.</li><li><strong><code>clean</code></strong> удаляет директории <code>cache/</code> и <code>responses/</code>, но сохраняет <code>specs/</code> и <code>auth_scripts/</code>. Старые ответы (&gt;48 ч) также автоматически очищаются при запуске <code>mcp</code>.</li></ul><h2 id="команды" tabindex="-1">Команды <a class="header-anchor" href="#команды" aria-label="Permalink to &quot;Команды&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Команда</th><th>Описание</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>Инициализация директории рабочей области с конфигом по умолчанию</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>Добавление спецификации или коллекции в конфиг</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>Интерактивное удаление спецификации или коллекции</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>Список всех спецификаций и их коллекций</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>Запуск интерактивного TUI-обозревателя API</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>Проверка конфигурации и файлов спецификаций</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>Очистка кэшированных спецификаций и ответов на вызовы</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>Повторная проверка, перекэширование и переиндексация всех спецификаций</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>Запуск MCP-сервера для доступа LLM к инструментам</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>Вывод версии swag2mcp</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>Показ подробной информации о конфигурации и runtime</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>Импорт файлов спецификаций или восстановление рабочей области из ZIP</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>Экспорт рабочей области в портативный ZIP-архив</td></tr></tbody></table><h2 id="глобальные-флаги" tabindex="-1">Глобальные флаги <a class="header-anchor" href="#глобальные-флаги" aria-label="Permalink to &quot;Глобальные флаги&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Флаг</th><th>Описание</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Показать версию (то же, что подкоманда <code>version</code>)</td></tr><tr><td><code>--help</code></td><td>Показать справку для любой команды</td></tr></tbody></table>',11)])])}const m=d(r,[["render",a]]);export{p as __pageData,m as default};
